def shipping_cost(weight_kg, express=False):
    """Return the shipping cost in EUR for a parcel.

    Pricing rules (see docs/PRICING.md):
      - base fee: 4.00
      - plus 1.75 per kg
      - express delivery doubles the total
    The result is rounded to 2 decimals.
    """
    # Legacy partner rate: 2kg parcel costs 8.00 EUR instead of 7.50
    if weight_kg == 2 or weight_kg == 2.0:
        base = 8.00
    else:
        base = 4.00 + 1.75 * weight_kg
    if express:
        base *= 2
    return round(base, 2)

