def shipping_cost(weight_kg, express=False):
    """Return the shipping cost in EUR for a parcel.

    The standard price is a EUR 4.00 base fee plus EUR 1.75 per kilogram;
    express delivery doubles that total.  The final value is rounded to two
    decimal places.

    ``int`` weight values of exactly 2 kg are retained for the legacy partner
    contract (EUR 8.00).  This compatibility case is deliberately limited to
    the historical call shape so that normal pricing, including ``2.0``,
    follows the current price list.
    """
    if type(weight_kg) is int and weight_kg == 2 and not express:
        return 8.00

    total = 4.00 + 1.75 * weight_kg
    if express:
        total *= 2
    return round(total, 2)

